<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { myMerchants, type MerchantWorkspace } from '../campus-merchant/workflow-api'
import { ApiError } from '../../campus-shared/http'
import AmapView from './AmapView.vue'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
import * as api from './api'
const stores = ref<MerchantWorkspace[]>([]), selected = ref(''), longitude = ref(''), latitude = ref(''), version = ref(0), loaded = ref(false), busy = ref(false), message = ref(''), page = ref(1), total = ref(0)
const editable = computed(() => { const s = stores.value.find(s => s.id === selected.value); return loaded.value && s?.status === 'APPROVED' && ['OWNER', 'MANAGER'].includes(s.role) })
async function list(target = 1) { busy.value = true; try { const result = await myMerchants(target); stores.value = result.items; total.value = result.total; page.value = result.page; selected.value = result.items[0]?.id ?? '' } catch (e) { message.value = e instanceof Error ? e.message : '门店加载失败' } finally { busy.value = false } }
async function load() { loaded.value = false; longitude.value = ''; latitude.value = ''; version.value = 0; message.value = ''; if (!selected.value) return; busy.value = true; try { const result = await api.location(selected.value); longitude.value = String(result.longitude); latitude.value = String(result.latitude); version.value = result.version; loaded.value = true } catch (e) { if (e instanceof ApiError && e.problem.code === 'LOCATION_NOT_SET') { loaded.value = true; message.value = '尚未设置位置。请确认坐标来源后填写。' } else message.value = e instanceof Error ? e.message : '位置加载失败' } finally { busy.value = false } }
async function save() { busy.value = true; message.value = ''; try { const result = await api.saveLocation(selected.value, { longitude: longitude.value, latitude: latitude.value, coordinateSystem: 'WGS84', version: version.value }); version.value = result.version; message.value = '门店位置已保存。' } catch (e) { message.value = e instanceof Error ? e.message : '保存失败，请刷新位置后重试' } finally { busy.value = false } }
watch(selected, () => void load()); onMounted(() => list())
</script>
<template><section><h1>门店位置</h1><p class="muted">仅使用明确来源的 WGS84 坐标。旧资料未标注坐标系的位置不会自动参与附近排序。高德/腾讯坐标须先完成供应商转换。</p><label for="locationStore">选择门店</label><select id="locationStore" v-model="selected" :disabled="busy"><option v-for="s in stores" :key="s.id" :value="s.id">{{ s.name }} · {{ s.role }}</option></select><PaginationBar :page="page" :size="20" :total="total" :disabled="busy" @change="list" /><p v-if="message" role="status">{{ message }}</p><form v-if="selected" class="workspace-card" @submit.prevent="save"><label for="storeLongitude">门店 WGS84 经度</label><input id="storeLongitude" v-model="longitude" type="number" min="-180" max="180" step="0.0000001" required :disabled="busy || !editable" /><label for="storeLatitude">门店 WGS84 纬度</label><input id="storeLatitude" v-model="latitude" type="number" min="-90" max="90" step="0.0000001" required :disabled="busy || !editable" /><div class="button-row"><button type="submit" :disabled="busy || !editable">保存门店位置</button><button type="button" class="secondary" :disabled="busy" @click="load">刷新位置</button></div></form><AmapView v-if="selected" :longitude="longitude" :latitude="latitude" /></section></template>
